"""Generate docs/stages.md from config/workbench/stages.yaml and the tunables in params.schema.yaml.

    python -m tools.workbench.gen_docs [--check]

--check exits 1 if the file on disk differs (a test runs it), so the reference never drifts.
"""
import argparse
import pathlib
import sys

from tools.workbench.stages import ROOT, Registry, primary_mode

OUT = ROOT / "docs" / "stages.md"


def render(reg):
    out = ["# Stages of the hardware phase", "",
           "GENERATED by `python -m tools.workbench.gen_docs` from `config/workbench/stages.yaml` and",
           "`config/params.schema.yaml` (tunables). Do not edit; edit those files. The workbench (codebase plan §12)",
           "runs these stages in this order; an arm run is locked until the stages it requires have passed on the",
           "arm and the stage itself has passed in dry run and mock.", "",
           "Modes: `dry-run`, `mock`, `arm` (a tool that talks to the arm); `form` (a checklist on the page);",
           "`analysis` (a script on recorded data). Status: built, planned (no tool yet), conditional.", "",
           "| # | Stage | Modes | Tool | Requires |", "|---|---|---|---|---|"]
    for sid in reg.order:
        s = reg.stages[sid]
        out.append(f"| {s['num']} | {s['title']} (`{sid}`) | {', '.join(s['modes'])} | "
                   f"{s['status']}: `{s['tool']}` | {', '.join(reg.stages[r]['num'] for r in s['requires']) or '-'} |")
    out.append("")
    for g, gtitle in reg.groups.items():
        out += [f"## {gtitle}", ""]
        for sid in reg.order:
            s = reg.stages[sid]
            if s["group"] != g:
                continue
            out += [f"### {s['num']} {s['title']}", "",
                    f"- **Purpose:** {s['purpose']}",
                    f"- **Plan:** {s['plan']}",
                    f"- **Runs on:** {', '.join(s['modes'])} (counts as passed in: {primary_mode(s)})"
                    + ("; repeated every session" if s["per_session"] else "")
                    + ("; a gate: it locks what follows but makes nothing stale" if s["gate"] else ""),
                    f"- **Tool:** `{s['tool']}` ({s['status']})"]
            if s["requires"]:
                out.append("- **Requires:** " + ", ".join(f"{reg.stages[r]['num']} {r}" for r in s["requires"]))
            if s["inputs"]:
                out.append("- **Inputs:** " + "; ".join(s["inputs"]))
            if s["adjust"]:
                adj = []
                for n in s["adjust"]:
                    d = reg.tunables[n]
                    rng = d.get("range") or d.get("values")
                    adj.append(f"`{n}` ({d.get('unit')}{', ' + str(rng) if rng else ''}; {d.get('marker')})")
                out.append("- **Adjust:** " + "; ".join(adj))
            crit = [f"{c['text']}" + (f" [`{c['coeff']}`]" if c.get("coeff") else "") + f" ({c['kind']})"
                    for c in s["criteria"].values()]
            crit += [f"{f['label']} (form)" for f in s["fields"].values() if f["type"] == "check"]
            if crit:
                out.append("- **Pass criteria:**")
                out += [f"  - {c}" for c in crit]
            out += [f"- **Output:** {s['output']}", ""]
    out += ["## Coefficients", "", "| Coefficient | Stage | Unit | Range | Default | Marker | Home | From |",
            "|---|---|---|---|---|---|---|---|"]
    for sid in reg.order:
        for n in reg.owned(sid):
            d = reg.tunables[n]
            rng = d.get("range") or d.get("values") or ""
            out.append(f"| `{n}` | {reg.stages[sid]['num']} | {d.get('unit')} | {rng} | "
                       f"{d.get('default', '') if d['home'] == 'store' else ''} | {d.get('marker')} | {d['home']} | {d.get('from')} |")
    return "\n".join(out) + "\n"


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args(argv)
    text = render(Registry())
    if a.check:
        if not OUT.exists() or OUT.read_text(encoding="utf-8") != text:
            print(f"{OUT} is out of date: run python -m tools.workbench.gen_docs", file=sys.stderr)
            return 1
        return 0
    OUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
